"use strict";export const POLL_MS=60000;const URL_META="meta[name=\"atlas-runnerstatus-url\"]";export function describeAge(seconds){const units=[["day",86400],["hour",3600],["minute",60]];for(const[name,size]of units){if(seconds>=size){const count=Math.floor(seconds/size);return count+" "+name+(count==1?"":"s")+" ago"}}return"less than a minute ago"}const RUNNERSTATUS_VOLATILE_FIELDS=["written","pid","running_taskids","status_age_seconds"];export function runnerStatusEqual(previous,next){if(previous==null||next==null){return previous===next}if((previous.stale||next.stale)&&previous.status_age_seconds!==next.status_age_seconds){return false}const fields=new Set([...Object.keys(previous),...Object.keys(next)].filter(field=>!RUNNERSTATUS_VOLATILE_FIELDS.includes(field)));for(const field of fields){const before=previous[field];const after=next[field];if(before===after){continue}if(JSON.stringify(before)!==JSON.stringify(after)){return false}}return true}export function runnerMessage(status,{showQueue=true}={}){if(status==null){return null}if(status.stale){const age=status.status_age_seconds!=null?" It last reported "+describeAge(status.status_age_seconds)+".":"";return"The task runner is not currently processing jobs."+age+" Queued tasks will start once it is back; there is no need to submit them again."}if(!status.queued_task_count||!showQueue){return null}const activity=status.maintenance?"maintenance sweep in progress;":status.slots_busy+" of "+status.numslots+" slots busy,";return"Task runner: "+activity+" "+status.queued_task_count+" unfinished "+(status.queued_task_count==1?"task":"tasks")+" from all users in the queue."}function pollingPaused(){return typeof document!=="undefined"&&document.hidden}export function createStore({url,poll=POLL_MS}){let status=null;let lastgoodfetch=null;let interval=null;const listeners=new Set;function publish(next){if(runnerStatusEqual(status,next)){return}status=next;for(const listener of[...listeners]){listener(status)}}function refresh(){return fetch(url,{credentials:"same-origin",headers:{"Accept":"application/json"}}).then(response=>response.json()).then(body=>{lastgoodfetch=Date.now();publish(body)}).catch(()=>{if(lastgoodfetch!=null&&Date.now()-lastgoodfetch>poll*5){publish(null)}})}function refreshIfVisible(){if(!pollingPaused()){refresh()}}function stop(){clearInterval(interval);interval=null;if(typeof document!=="undefined"){document.removeEventListener("visibilitychange",refreshIfVisible)}status=null;lastgoodfetch=null}function subscribe(listener){listeners.add(listener);if(interval==null){refresh();interval=setInterval(()=>{if(!pollingPaused()){refresh()}},poll);if(typeof document!=="undefined"){document.addEventListener("visibilitychange",refreshIfVisible)}}listener(status);let subscribed=true;return()=>{if(!subscribed){return}subscribed=false;listeners.delete(listener);if(listeners.size===0){stop()}}}return{subscribe,refresh,stop,current:()=>status}}let pagestore=null;function pageStore(){if(pagestore==null){const meta=document.querySelector(URL_META);pagestore=meta!=null?createStore({url:meta.content}):{subscribe:listener=>{listener(null);return()=>{}},refresh:()=>{},stop:()=>{},current:()=>null}}return pagestore}export function subscribe(listener){return pageStore().subscribe(listener)}function warningMark(document){const ns="http://www.w3.org/2000/svg";const svg=document.createElementNS(ns,"svg");svg.setAttribute("class","sitenotice-warnmark");svg.setAttribute("viewBox","0 0 16 16");svg.setAttribute("aria-hidden","true");svg.setAttribute("focusable","false");const triangle=document.createElementNS(ns,"path");triangle.setAttribute("d","M8 2.4 14.8 13.8H1.2z");triangle.setAttribute("fill","none");triangle.setAttribute("stroke","currentColor");triangle.setAttribute("stroke-width","1.4");triangle.setAttribute("stroke-linejoin","round");const bang=document.createElementNS(ns,"path");bang.setAttribute("d","M8 6.4v3.2");bang.setAttribute("stroke","currentColor");bang.setAttribute("stroke-width","1.4");bang.setAttribute("stroke-linecap","round");const dot=document.createElementNS(ns,"circle");dot.setAttribute("cx","8");dot.setAttribute("cy","11.7");dot.setAttribute("r","0.8");dot.setAttribute("fill","currentColor");svg.append(triangle,bang,dot);return svg}export function renderInto(box,status){const line=box.querySelector(".sitenotice-runner");if(line==null){return}const message=runnerMessage(status,{showQueue:box.hasAttribute("data-showqueue")});const stale=status!=null&&Boolean(status.stale);if(message==null){line.textContent=""}else if(stale){line.replaceChildren(warningMark(box.ownerDocument),message)}else{line.textContent=message}box.classList.toggle("stale",stale)}export function start(box){return subscribe(status=>renderInto(box,status))}const sitenotice=typeof document!=="undefined"?document.getElementById("sitenotice"):null;if(sitenotice!=null){start(sitenotice)}
